args.CommandLine:
node -e "
import('./server/dist/services/gee/GeeAuthService.js').then(async ({ GeeAuthService }) => {
  const auth = GeeAuthService.getInstance();
  const token = await auth.getAccessToken();

  async function testPayload(name, expressionValues) {
    const url = 'https://earthengine.googleapis.com/v1alpha/projects/monitoring-system-506515/image:export';
    const payload = {
      description: 'TEST_' + name,
      expression: { values: expressionValues, result: 'clipped' },
      fileExportOptions: {
        fileFormat: 'GEO_TIFF',
        driveDestination: { folder: 'MonitoringExports', filenamePrefix: 'TEST_' + name },
        geoTiffOptions: { cloudOptimized: true }
      },
      maxPixels: '1000000000'
    };
    const res = await fetch(url, {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json', 'X-Goog-User-Project': 'monitoring-system-506515' },
      body: JSON.stringify(payload)
    });
    console.log(name, '-> Status:', res.status, (await res.text()).slice(0, 300));
  }

  const baseImage = { functionInvocationValue: { functionName: 'Image.load', arguments: { id: { constantValue: 'COPERNICUS/S2_SR_HARMONIZED/20200109T051201_20200109T051844_T43PHM' } } } };
  const geom = { functionInvocationValue: { functionName: 'GeometryConstructors.Polygon', arguments: { coordinates: { constantValue: [[[78.0747, 10.1182],[78.0867, 10.1118],[78.0939, 10.1196],[78.0890, 10.1235],[78.0797, 10.1228],[78.0747, 10.1182]]] } } } };
  const selQa = { functionInvocationValue: { functionName: 'Image.select', arguments: { input: { valueReference: 'raw_image' }, bandSelectors: { constantValue: ['SCL'] } } } };
  const selOpt = { functionInvocationValue: { functionName: 'Image.select', arguments: { input: { valueReference: 'raw_image' }, bandSelectors: { constantValue: ['B2', 'B3', 'B4', 'B8', 'B11', 'B12'] } } } };

  // Test 1: Image.toUint16 with { image: ... }
  await testPayload('toUint16_image', {
    raw_image: baseImage, geom, selected_qa: selQa, selected_optical: selOpt,
    qa_uint16: { functionInvocationValue: { functionName: 'Image.toUint16', arguments: { image: { valueReference: 'selected_qa' } } } },
    selected_bands: { functionInvocationValue: { functionName: 'Image.addBands', arguments: { dstImg: { valueReference: 'selected_optical' }, srcImg: { valueReference: 'qa_uint16' } } } },
    clipped: { functionInvocationValue: { functionName: 'Image.clip', arguments: { input: { valueReference: 'selected_bands' }, geometry: { valueReference: 'geom' } } } }
  });

  // Test 2: Image.toUint16 with { input: ... }
  await testPayload('toUint16_input', {
    raw_image: baseImage, geom, selected_qa: selQa, selected_optical: selOpt,
    qa_uint16: { functionInvocationValue: { functionName: 'Image.toUint16', arguments: { input: { valueReference: 'selected_qa' } } } },
    selected_bands: { functionInvocationValue: { functionName: 'Image.addBands', arguments: { dstImg: { valueReference: 'selected_optical' }, srcImg: { valueReference: 'qa_uint16' } } } },
    clipped: { functionInvocationValue: { functionName: 'Image.clip', arguments: { input: { valueReference: 'selected_bands' }, geometry: { valueReference: 'geom' } } } }
  });

  // Test 3: Image.toUint16 with { value: ... }
  await testPayload('toUint16_value', {
    raw_image: baseImage, geom, selected_qa: selQa, selected_optical: selOpt,
    qa_uint16: { functionInvocationValue: { functionName: 'Image.toUint16', arguments: { value: { valueReference: 'selected_qa' } } } },
    selected_bands: { functionInvocationValue: { functionName: 'Image.addBands', arguments: { dstImg: { valueReference: 'selected_optical' }, srcImg: { valueReference: 'qa_uint16' } } } },
    clipped: { functionInvocationValue: { functionName: 'Image.clip', arguments: { input: { valueReference: 'selected_bands' }, geometry: { valueReference: 'geom' } } } }
  });
});
"
